// Approximate NOAA fractional-year equations. Azimuth is clockwise from true north.
export function solarPosition({date,minutes,latitude,longitude,timezone}){if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||![minutes,latitude,longitude,timezone].every(Number.isFinite)||minutes<0||minutes>=1440||Math.abs(latitude)>89||Math.abs(longitude)>180||timezone < -12||timezone>14)throw Error('Invalid solar site settings');const day=new Date(date+'T12:00:00Z');if(!Number.isFinite(+day)||day.toISOString().slice(0,10)!==date)throw Error('Invalid date');const year=day.getUTCFullYear(),days=(Date.UTC(year+1,0,1)-Date.UTC(year,0,1))/86400000,doy=Math.floor((Date.UTC(year,day.getUTCMonth(),day.getUTCDate())-Date.UTC(year,0,1))/86400000)+1,g=2*Math.PI/days*(doy-1+(minutes/60-12)/24),eq=229.18*(.000075+.001868*Math.cos(g)-.032077*Math.sin(g)-.014615*Math.cos(2*g)-.040849*Math.sin(2*g)),decl=.006918-.399912*Math.cos(g)+.070257*Math.sin(g)-.006758*Math.cos(2*g)+.000907*Math.sin(2*g)-.002697*Math.cos(3*g)+.00148*Math.sin(3*g),tst=((minutes+eq+4*longitude-60*timezone)%1440+1440)%1440,h=(tst/4-180)*Math.PI/180,lat=latitude*Math.PI/180,elevation=Math.asin(Math.max(-1,Math.min(1,Math.sin(lat)*Math.sin(decl)+Math.cos(lat)*Math.cos(decl)*Math.cos(h))))*180/Math.PI,azimuth=(Math.atan2(Math.sin(h),Math.cos(h)*Math.sin(lat)-Math.tan(decl)*Math.cos(lat))*180/Math.PI+180+360)%360;return {elevation,azimuth}}
export function wallSun(position,wallFacing){if(!Number.isFinite(wallFacing))throw Error('Invalid wall orientation');const relative=((position.azimuth-wallFacing+540)%360)-180,e=position.elevation*Math.PI/180,a=relative*Math.PI/180;return {relative,direct:position.elevation>0&&Math.cos(a)>0,direction:{x:Math.sin(a)*Math.cos(e),y:Math.sin(e),z:-Math.cos(a)*Math.cos(e)}}}
export function penetration(height,elevation,relative){if(elevation<=0||Math.abs(relative)>=90)return 0;return height*Math.cos(relative*Math.PI/180)/Math.tan(elevation*Math.PI/180)}
// Diffuse daylight depends on the sun's height, not which facade faces it.
// Values are presentation lighting, not measured illuminance.
export function daylightEnvironment(elevation){if(!Number.isFinite(elevation))throw Error('Invalid sun height');const x=Math.max(0,Math.min(1,(elevation+8)/20)),day=x*x*(3-2*x);return {day,sunStrength:elevation>0?3.8*Math.max(.35,Math.pow(Math.max(0,Math.sin(elevation*Math.PI/180)),.3)):0,hemisphere:.12+2.08*day,bounce:.025+.375*day,fill:.02+.58*day,exposure:1.15}}
